// Die Antwort des lokalen Modells wird geprueft, bevor sie den Aufrufer erreicht.
// Warum: Ollama antwortet auch dann mit HTTP 200, wenn das angeforderte Modell gar nicht
// geladen ist oder der Kontext ueberlaeuft — der Body enthaelt dann eine Fehlermeldung
// oder einen leeren String. Ohne diese Pruefung liefert der Webhook eine leere Antwort
// und die aufrufende Anwendung zeigt sie als gueltiges Ergebnis an.
const antwortRoh = $input.first().json || {};
const anfrage = $('Anfrage entgegennehmen').first().json.body || {};

// Ollama liefert je nach Endpunkt /api/chat (message.content) oder /api/generate (response).
const text = String(antwortRoh.message?.content ?? antwortRoh.response ?? '').trim();
const fehlertext = String(antwortRoh.error || '').trim();

const eingabe = String(anfrage.frage || '');
const brauchbar = fehlertext === '' && text.length >= 2;

return [{
  json: {
    antwort: text,
    brauchbar,
    modell: antwortRoh.model || 'unbekannt',
    zeichen_eingabe: eingabe.length,
    zeichen_antwort: text.length,
    // Ollama gibt die Dauer in Nanosekunden zurueck — fuer das Protokoll in Millisekunden.
    dauer_ms: antwortRoh.total_duration ? Math.round(antwortRoh.total_duration / 1e6) : null,
    tokens_antwort: antwortRoh.eval_count ?? null,
    zeitpunkt: new Date().toISOString(),
    verarbeitung: 'lokal',
    fehlergrund: brauchbar
      ? ''
      : (fehlertext || 'Das lokale Modell hat eine leere Antwort geliefert — vermutlich ist das Modell nicht geladen oder der Kontext zu lang.'),
  },
}];
